$fn = 64;

// Jar parameters
jar_d = 40;
jar_r = jar_d / 2;
jar_h = 120;

// Stand parameters
wall = 2.5;                 // Wall thickness around jars
base_t = 3;                 // Bottom plate thickness
step_h = 30;                // Height step between rows (3cm)
cup_h = 35;                 // How deep the cup holds each jar
gap = 0.5;                  // Clearance for easy insertion/removal
scoop_angle = 50;           // Angular width of front scoop (degrees)

hole_r = jar_r + gap;       // Hole radius with clearance
pitch = jar_d + 2*gap + wall; // Center-to-center distance
cols = 3;
rows = 3;

// Overall dimensions
total_w = cols * pitch + wall;
total_d = rows * pitch + wall;

echo("Total width:", total_w);
echo("Total depth:", total_d);
echo("Max height:", base_t + cup_h + (rows-1)*step_h);

module jar_cup(row) {
    // Height of the base for this row
    bz = base_t + row * step_h;
    // Height of the top of the cup wall
    top_z = bz + cup_h;

    difference() {
        // Outer cylinder (cup wall)
        translate([0, 0, bz])
            cylinder(r = hole_r + wall, h = cup_h);

        // Inner hole (jar cavity) - goes all the way up
        translate([0, 0, bz])
            cylinder(r = hole_r, h = cup_h + 50);

        // Top chamfer for easy insertion
        translate([0, 0, top_z - 1.5])
            cylinder(r1 = hole_r, r2 = hole_r + 2, h = 1.51);

        // Front scoop for easy removal - U-shaped cutout in front wall
        // Cut from the front, removing a portion of the cup wall
        scoop_depth = cup_h * 0.6;  // How deep the scoop cuts down
        translate([0, 0, top_z - scoop_depth])
            linear_extrude(height = scoop_depth + 1)
                // Pie slice pointing toward -Y (front)
                intersection() {
                    translate([0, -50, 0]) square([100, 100], center=true);
                    difference() {
                        circle(r = hole_r + wall + 1);
                        circle(r = hole_r - 0.01);
                    }
                    // Limit angular width
                    rotate([0, 0, -90])
                    polygon([
                        [0, 0],
                        [60 * cos(-scoop_angle/2), 60 * sin(-scoop_angle/2)],
                        [60 * cos(scoop_angle/2), 60 * sin(scoop_angle/2)]
                    ]);
                }
    }
}

module base_platform() {
    // Stepped base platforms
    for (row = [0 : rows - 1]) {
        bz = row * step_h;
        translate([0, row * pitch, 0])
            cube([total_w, pitch + wall, base_t + bz]);
    }

    // Fill between rows smoothly - add ramps
    for (row = [1 : rows - 1]) {
        prev_top = base_t + (row - 1) * step_h;
        curr_top = base_t + row * step_h;
        translate([0, row * pitch, 0])
            cube([total_w, wall, curr_top]);
    }
}

module stand() {
    union() {
        // Base platforms
        base_platform();

        // Jar cups
        for (row = [0 : rows - 1]) {
            for (col = [0 : cols - 1]) {
                cx = wall + hole_r + col * pitch;
                cy = wall + hole_r + row * pitch;

                translate([cx, cy, 0])
                    jar_cup(row);
            }
        }
    }
}

// Build the complete stand
module complete_stand() {
    difference() {
        stand();

        // Cut flat bottom
        translate([-1, -1, -10])
            cube([total_w + 2, total_d + 2, 10]);
    }
}

complete_stand();
'}

