{'content': '// IKEA Citronhaj Spice Jar Stand - 3x3 Tiered
// Jar: 40mm diameter, 120mm height
// Stand holds jars securely while allowing easy removal

$fn = 72;

// === Jar parameters ===
jar_d = 40;
jar_r = jar_d / 2;

// === Stand parameters ===
wall = 2.5;                 // Wall thickness around jars
base_t = 3;                 // Bottom plate thickness
step_h = 30;                // Height step between rows (3cm)
cup_h = 35;                 // How deep each cup holds the jar
gap = 0.5;                  // Clearance around jar for easy fit
scoop_ang = 70;             // Angular width of front scoop

// === Derived dimensions ===
hole_r = jar_r + gap;       // 20.5mm
pitch = jar_d + 2*gap + wall; // 43.5mm center-to-center
cols = 3;
rows = 3;

total_w = cols * pitch + wall;  // 133mm
total_d = rows * pitch + wall;  // 133mm
max_h = base_t + cup_h + (rows-1) * step_h;  // 98mm

module stand() {
    difference() {
        // === SOLID BODY ===
        union() {
            for (row = [0 : rows-1]) {
                h = base_t + cup_h + row * step_h;
                y0 = row * pitch;
                depth = pitch + (row == rows-1 ? wall : 0);
                translate([0, y0, 0])
                    cube([total_w, depth, h]);
            }
        }

        // === CUT-OUTS ===
        for (row = [0 : rows-1]) {
            for (col = [0 : cols-1]) {
                cx = wall + hole_r + col * pitch;
                cy = wall + hole_r + row * pitch;
                bz = base_t + row * step_h;    // Floor of this cup
                top_z = bz + cup_h;             // Top of cup walls

                // --- Main jar cavity ---
                translate([cx, cy, bz])
                    cylinder(r = hole_r, h = max_h + 10);

                // --- Top entry chamfer (easy insertion) ---
                translate([cx, cy, top_z - 1.5])
                    cylinder(r1 = hole_r, r2 = hole_r + wall + 0.5, h = 2);

                // --- Front scoop for easy jar removal ---
                // Removes a wedge of the front cup wall so you can 
                // grip the jar with your fingers
                scoop_h = cup_h * 0.55;
                translate([cx, cy, top_z - scoop_h])
                    linear_extrude(height = scoop_h + 10)
                    intersection() {
                        // Ring shape (the wall)
                        difference() {
                            circle(r = hole_r + wall + 1);
                            circle(r = hole_r - 0.1);
                        }
                        // Front-facing wedge
                        rotate([0, 0, -90])
                        polygon([
                            [0, 0],
                            [60*cos(-scoop_ang/2), 60*sin(-scoop_ang/2)],
                            [60*cos(scoop_ang/2), 60*sin(scoop_ang/2)]
                        ]);
                    }

                // --- Drainage / weight-reduction hole ---
                translate([cx, cy, -0.1])
                    cylinder(r = 5, h = bz + 0.2);
            }
        }

        // === STEP EDGE CHAMFERS ===
        // Chamfer the front-facing edge of each step for aesthetics
        for (row = [1 : rows-1]) {
            sz = base_t + cup_h + (row-1) * step_h;
            sy = row * pitch;
            translate([-0.5, sy + 3, sz])
                rotate([0, 90, 0])
                linear_extrude(height = total_w + 1)
                polygon([[0.1, 0], [0.1, -3.1], [-3, 0]]);
        }

        // Bottom front chamfer
        translate([-0.5, 2, 0])
            rotate([0, 90, 0])
            linear_extrude(height = total_w + 1)
            polygon([[0.1, 0], [0.1, -2.1], [-2, 0]]);

        // === WEIGHT REDUCTION: hollow out thick step blocks ===
        for (row = [1 : rows-1]) {
            // The solid block under each step is very thick, hollow it out
            inner_margin = wall + 3;
            y0 = row * pitch + inner_margin;
            h_block = row * step_h - base_t;
            if (h_block > 5) {
                translate([inner_margin, y0, base_t])
                    cube([total_w - 2*inner_margin, 
                          pitch - 2*inner_margin, 
                          h_block]);
            }
        }
    }
}

stand();
'}

